import { useQuery } from '@tanstack/react-query';

/**
 * The buildings the area view knows about, read from assets/3d/buildings/manifest.json
 * (generated by `npm run build:buildings`). Each entry maps a geographic footprint to its
 * detailed model: the model's origin is the footprint centre (`anchor`), +x east, -z north,
 * rotated clockwise from north by `heading_deg`. Entries with `model: null` are footprints
 * only and cannot be opened for inspection.
 */
export interface BuildingEntry {
  id: string;
  name: string;
  use: string;
  geo_building_id: string;
  anchor: { lat: number; lng: number; heading_deg: number };
  footprint: { width_m: number; depth_m: number };
  height_m: number;
  floors: { level: number; label: string; elevation_m: number }[];
  model: null | {
    url: string;
    source: 'authored' | 'survey';
    components: Record<string, number>;
  };
  note: string;
  /** Row in the backend `buildings` table, once buildings are seeded there. */
  db_id?: number | null;
}

export interface BuildingManifest {
  version: number;
  area: { name: string; frame: string };
  buildings: BuildingEntry[];
}

export const BUILDING_MANIFEST_URL = '/3d/buildings/manifest.json';

export function useBuildingManifest() {
  return useQuery({
    queryKey: ['building-manifest'],
    staleTime: Infinity,
    queryFn: async (): Promise<BuildingManifest> => {
      const res = await fetch(BUILDING_MANIFEST_URL);
      if (!res.ok) throw new Error(`Building manifest unavailable (${res.status})`);
      return res.json();
    }
  });
}

const EARTH_M_PER_DEG = 111_320;

/** Offsets a point by east/north metres. Accurate to centimetres over a few hundred metres. */
export function offsetLatLng(lat: number, lng: number, east: number, north: number) {
  return {
    lat: lat + north / EARTH_M_PER_DEG,
    lng: lng + east / (EARTH_M_PER_DEG * Math.cos((lat * Math.PI) / 180))
  };
}

/** Great-circle distance in metres (haversine). */
export function distanceMetres(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const r = 6_371_000;
  const toRad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * toRad;
  const dLng = (b.lng - a.lng) * toRad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * toRad) * Math.cos(b.lat * toRad) * Math.sin(dLng / 2) ** 2;
  return 2 * r * Math.asin(Math.sqrt(h));
}

/** The footprint's corners as lat/lng, clockwise from the north-west corner. */
export function footprintCorners(b: BuildingEntry) {
  const hw = b.footprint.width_m / 2;
  const hd = b.footprint.depth_m / 2;
  const h = (b.anchor.heading_deg * Math.PI) / 180;
  // Model frame: +x east, +z south; heading rotates clockwise seen from above.
  return [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]].map(([x, z]) => {
    const east = x * Math.cos(h) - z * Math.sin(h);
    const north = -x * Math.sin(h) - z * Math.cos(h);
    return offsetLatLng(b.anchor.lat, b.anchor.lng, east, north);
  });
}
